webpackJsonp([1],{"5/Uj":function(n,r){},XWcV:function(n,r,b){"use strict";Object.defineProperty(r,"__esModule",{value:!0});var v=b("/5sW"),_={render:function(){var n=this;n.$createElement;n._self._c;return n._m(0)},staticRenderFns:[function(){var n=this,r=n.$createElement,b=n._self._c||r;return b("div",{staticClass:"container"},[b("div",{staticClass:"content"},[n._v("\n            ● 本政策适用于北京智同世纪有限公司的娃娃路产品及相关服务。"),b("br"),n._v("\n● 您所使用的“娃娃路”应用的运营者的公司名称为北京智同世纪科技有限公司，注册地址为：北京市海淀区大钟寺13号院1号楼地下一层A01-26，个人信息保护相关负责人联系方式为：13901147305。"),b("br"),n._v("\n● 最近更新时间：2022.12.31  。"),b("br"),n._v("\n● 生效时间：2023.1. 1 。"),b("br"),n._v("\n● 北京智同世纪有限公司（以下统称“我们”）深知个人信息对您的重要性，并会尽力保护您的个人信息安全可靠，我们致力于维持您对我们的信任，恪守以下原则，保护您的个人信息：权责一致原则，目的明确原则，选择同意原则，最少够用原则，确保安全原则，主体参与原则，公开透明原则等等。同时我们承诺，我们将按业界成熟的安全解决方案，采取相应的安全保护措施来保护您的个人信息。"),b("br"),n._v("\n● 请在使用我们的产品、服务前，仔细阅读并了解本《隐私政策》。"),b("br"),n._v("\n● 本政策中的个人常用设备信息是指：包括硬件序列号、设备MAC地址、软件列表、唯一设备识别码（如IMEI/IDFA/○PENUDID/GUID、SIM卡IMSI信息等）等在内的描述个人常用设备基本情况的信息。"),b("br"),n._v("\n● 本政策中的个人位置信息是指：包括精准定位信息等。"),b("br"),n._v("\n\n一、我们如何收集和使用您的个人信息"),b("br"),n._v("\n● 个人信息是指以电子或者其他方式记录的能够单独或者与其他信息结合识别特定自然人身份或者反映特定自然人活动情况的各种信息，我们会出于本政策所述的以下目的，收集和使用您的个人信息；"),b("br"),n._v("\n● 我们将向您提供下列服务，并在提供下列服务时分别收集如下所列的信息；"),b("br"),n._v("\n1、业务功能：注册成为用户。当您注册娃娃路服务时，为完成创建账号，您需要提供以下信息供我们收集：设备权限、手机号码、昵称、年龄、性别、个人头像图片，收集这些信息是为了帮助你完成娃娃路注册，获取娃娃路的账号，并以此保护您娃娃路帐号的安全。"),b("br"),n._v("\n● 为保障平台安全和运营安全，我们会申请系统权限收集手机号码和安装设备IMEI、IMSI、本机应用安装列表等设备信息用于平台安全风控。"),b("br"),n._v("\n● 手机号码、个人照片属于敏感信息，收集此类信息是为了满足国家法律法规的网络实名制要求以及完成娃娃路账号的注册。"),b("br"),n._v("\n● 若您不提供这类信息，您可能无法正常使用我们的服务。"),b("br"),n._v("\n● 您提供的上述信息，将在您使用本服务期间持续授权我们使用。我们会一直保存您的信息直至您注销账号。在您注销账号时，我们将停止使用并删除上述信息。"),b("br"),n._v("\n● 上述信息仅存储于中华人民共和国境内，如需跨境传输，我们将会单独征得您的授权同意。"),b("br"),n._v("\n2、业务功能：练习。当您使用娃娃路闯关练习服务时，软件会记录您的练习内容、时间和设备信息等。"),b("br"),b("br"),n._v("\n \n二、我们如何共享、转让、公开披露您的个人信息"),b("br"),n._v("\n共享"),b("br"),n._v("\n● 我们不会与娃娃路服务提供者以外的公司、组织和个人共享您的个人信息，但以下情况除外："),b("br"),n._v("\n● 1、在获取明确同意的情况下共享：获得您的明确同意后，我们会与其他方共享您的个人信息；"),b("br"),n._v("\n● 2、在法定情形下的共享：我们可能会根据法律法规规定、诉讼争议解决需要，或按行政、司法机关依法提出的要求，对外共享您的个人信息；"),b("br"),n._v("\n● 3、与关联公司间共享：您的个人信息不会与我们的关联公司共享；"),b("br"),n._v("\n● 4、与授权合作伙伴共享：仅为实现本隐私政策中声明的目的，我们的某些服务将由我们和授权合作伙伴共同提供。我们可能会与合作伙伴共享您的某些个人信息，以提供更好的客户服务和用户体验。例如安排合作伙伴提供服务。我们仅会出于合法、正当、必要、特定、明确的目的共享您的个人信息，并且只会共享提供服务所必要的个人信息。我们的合作伙伴无权将共享的个人信息用于与产品或服务无关的其他用途。"),b("br"),n._v("\n● 我们将信息发送给支持我们业务的供应商、服务提供商和其他合作伙伴，这些支持包括提供技术基础设施服务、分析我们服务的使用方式、衡量广告和服务的有效性、提供客户服务、支付便利或进行学术研究和调查。"),b("br"),n._v("\n● 对我们与之共享个人信息的公司、组织和个人，我们会与其签署严格的数据保护协定，要求其按照我们的说明、本隐私政策以及其他任何相关的保密和安全措施来处理个人信息。"),b("br"),n._v("\n转让"),b("br"),n._v("\n● 我们不会将您的个人信息转让给任何公司、组织和个人，但以下情况除外："),b("br"),n._v("\n● 1、在获取明确同意的情况下转让：获得您的明确同意后，我们会向其他方转让您的个人信息；"),b("br"),n._v("\n● 2、在涉及合并、收购或破产清算情形，或其他涉及合并、收购或破产清算情形时，如涉及到个人信息转让，我们会要求新的持有您个人信息的公司、组织继续受本政策的约束，否则我们将要求该公司、组织和个人重新向您征求授权同意。"),b("br"),n._v("\n公开披露"),b("br"),n._v("\n● 我们仅会在以下情况，公开披露您的个人信息："),b("br"),n._v("\n● 1、获得您明确同意或基于您的主动选择，我们可能会公开披露您的个人信息；"),b("br"),n._v("\n● 2、如果我们确定您出现违反法律法规或严重违反娃娃路相关协议规则的情况，或为保护娃娃路及其关联公司用户或公众的人身财产安全免遭侵害，我们可能依据法律法规或娃娃路相关协议规则征得您同意的情况下披露关于您的个人信息，包括相关违规行为以及娃娃路已对您采取的措施。"),b("br"),n._v("\n● 共享、转让、公开披露个人信息时事先征得授权同意的例外"),b("br"),n._v("\n● 以下情形中，共享、转让、公开披露您的个人信息无需事先征得您的授权同意："),b("br"),n._v("\n○ 1、与国家安全、国防安全有关的；"),b("br"),n._v("\n○ 2、与公共安全、公共卫生、重大公共利益有关的；"),b("br"),n._v("\n○ 3、与犯罪侦查、起诉、审判和判决执行等有关的；"),b("br"),n._v("\n○ 4、出于维护您或其他个人的生命、财产等重大合法权益但又很难得到本人同意的；"),b("br"),n._v("\n○ 5、您自行向社会公众公开的个人信息；"),b("br"),n._v("\n○ 6、从合法公开披露的信息中收集个人信息的，如合法的新闻报道、政府信息公开等渠道。"),b("br"),n._v("\n● 根据法律规定，共享、转让经去标识化处理的个人信息，且确保数据接收方无法复原并重新识别个人信息主体的，不属于个人信息的对外共享、转让及公开披露行为，对此类数据的保存及处理将无需另行向您通知并征得您的同意。"),b("br"),b("br"),n._v("\n\n三、我们如何保护您的个人信息"),b("br"),n._v("\n● 为了保护您的信息安全，我们将严格遵守法律法规等规范性文件要求的技术措施和操作流程保护您的信息秘密，同时："),b("br"),n._v("\n● 1.我们已采取符合业界通用解决方案、合理可行的安全防护措施保护您提供的个人信息安全，防止个人信息遭到未经授权访问、公开披露、使用、修改、损坏或丢失。我们会使用加密技术提高个人信息的安全性；我们会使用受信赖的保护机制防止个人信息遭到恶意攻击；我们建立严格的内部控制制度，建立完善、充分的管理流程，我们会部署访问控制机制，尽力确保只有授权人员才可访问个人信息；以及我们会举办安全和隐私保护培训课程，加强员工对于保护个人信息重要性的认识。"),b("br"),n._v("\n● 2.我们有行业先进的以数据为核心，围绕数据生命周期进行的数据安全管理体系，从组织建设、制度设计、人员管理、产品技术等方面多维度提升整个系统的安全性。"),b("br"),n._v("\n● 3.我们会采取合理可行的措施，尽力避免收集无关的个人信息。我们只会在达成本政策所述目的所需的期限内保留您的个人信息，除非需要延长保留期或受到法律的允许。"),b("br"),n._v("\n● 4.互联网并非绝对安全的环境，我们强烈建议您不要使用非娃娃路推荐的通信方式发送个人信息。您可以通过我们的服务建立联系和相互分享。当您通过我们的服务创建交流、交易或分享时，您可以自主选择沟通、交易或分享的对象，作为能够看到您的交易内容、联络方式、交流信息或分享内容等相关信息的第三方。"),b("br"),n._v("\n● 如您发现自己的个人信息尤其是您的账户或密码发生泄露，请您立即联络娃娃路客服，以便我们根据您的申请采取相应措施。"),b("br"),n._v("\n● 请注意，您在使用我们服务时自愿共享甚至公开分享的信息，可能会涉及您或他人的个人信息甚至个人敏感信息，请您更加谨慎地考虑，是否在使用我们的服务时共享甚至公开分享相关信息。"),b("br"),n._v("\n● 请使用复杂密码，协助我们保证您的账号安全。我们将尽力保障您发送给我们的任何信息的安全性。"),b("br"),n._v("\n● 我们将按照法律法规的要求更新并公开安全风险、个人信息安全影响评估等报告的内容。"),b("br"),n._v("\n● 互联网环境并非百分之百安全，我们将尽力确保或担保您发送给我们的任何信息的安全性。如果我们的物理、技术或管理防护设施遭到破坏，导致信息被非授权访问、公开披露、篡改或毁坏，导致您的合法权益受损，我们将承担相应的法律责任。"),b("br"),n._v("\n● 在不幸发生个人信息安全事件后，我们将依照法律法规的要求，及时向您告知：安全事件的基本情况和可能的影响、我们已采取或将要采取的处置措施，您可自主防范和降低风险的建议、对您的补救措施等。我们将及时将事件相关情况以推送通知的方式告知您，并采取合理有效的方式发送公告。"),b("br"),n._v("\n● 同时，我们还将按照监管部门要求，主动上报个人信息安全事件的处置情况。"),b("br"),n._v("\n\n四、您如何管理您的个人信息/您的权利"),b("br"),n._v("\n个人信息查询"),b("br"),n._v("\n● 您有权访问您的个人信息，法律法规规定的例外情况除外。您可以通过以下方式自行访问您的个人信息："),b("br"),n._v("\n● 账户信息——如果您希望访问或编辑您的账户中的个人信息、设置隐私与权限、设置消息提醒与聊天、更改您的绑定手机号与密码、关闭您的账户等，您可以通过登录账号通过“我的管理”执行此类操作。"),b("br"),n._v("\n● 个人资料——如果您希望访问或编辑您个人资料中的昵称、头像以及其他资料，您可以通过登录账户执行此类操作。"),b("br"),n._v("\n● 如果您无法通过上述路径访问该等个人信息，您可以随时通过娃娃路官方客服与我们取得联系。我们将在15天内回复您的访问请求。"),b("br"),n._v("\n● 对于您在使用我们的产品或服务过程中产生的其他个人信息，我们将根据相关安排向您提供。"),b("br"),n._v("\n● 您可以通过与娃娃路客服联系的方式，申请个人信息副本。"),b("br"),n._v("\n个人信息更正"),b("br"),n._v("\n● 当您发现我们处理的关于您的个人信息有错误时，您有权要求我们做出更正或补充。您可以通过本条“个人信息查询”中列明的方式提出更正或补充申请。"),b("br"),n._v("\n个人信息删除"),b("br"),n._v("\n● 您可以通过本条“个人信息查询”中列明的方式删除您的部分个人信息。"),b("br"),n._v("\n● 在以下情形中，您可以向我们提出删除个人信息的请求："),b("br"),n._v("\n○ 1、如果我们处理个人信息的行为违反法律法规；"),b("br"),n._v("\n○ 2、如果我们收集、使用您的个人信息，却未征得您的明确同意；"),b("br"),n._v("\n○ 3、如果我们处理个人信息的行为严重违反了与您的约定；"),b("br"),n._v("\n○ 4、如果您不再使用我们的产品或服务，或您主动注销了账号；"),b("br"),n._v("\n○ 5、如果我们永久不再为您提供产品或服务。"),b("br"),n._v("\n● 注销账号：注销账号功能途径（我的管理-其它信息-账号注销）"),b("br"),n._v("\n● 若我们决定响应您的删除请求，我们还将同时尽可能通知从我们处获得您的个人信息的主体，要求其及时删除，除非法律法规另有规定，或这些主体获得您的独立授权。"),b("br"),n._v("\n● 当您从我们的服务中删除信息后，我们可能不会立即从备份系统中删除相应的信息，但会在备份更新时删除这些信息。"),b("br"),n._v("\n用户账号迁移和注销"),b("br"),n._v("\n● 您如果在别的设备登录同一账号，则原设备已登录账号自动关闭，账户余额可以在新的设备上继续使用，但已下载关卡不能迁移。"),b("br"),n._v("\n● 您也可以通过娃娃路官方客服提交账户注销申请。在您主动注销账户之后，我们将停止为您提供产品或服务，根据相应法律的要求删除您的个人信息。"),b("br"),n._v("\n撤回已同意的授权"),b("br"),n._v("\n● 每个业务功能需要一些基本的个人信息才能得以完成。除此之外，对于额外个人信息的收集和使用，您可以自行或娃娃路与客服联系给予或收回您的授权同意。"),b("br"),n._v("\n● 当您收回同意后，我们将不再处理相应的个人信息。但您收回同意的决定，不会影响此前基于您的授权而开展的个人信息处理。"),b("br"),n._v("\n约束信息系统自动决策"),b("br"),n._v("\n● 在某些业务功能中，我们可能仅依据信息系统、算法等在内的非人工自动决策机制做出决定。如果这些决定显著影响您的合法权益，您有权要求我们做出解释，我们也将在不侵害娃娃路商业秘密或其他用户权益、社会公共利益的前提下提供申诉方法。"),b("br"),n._v("\n响应您的上述请求"),b("br"),n._v("\n● 为保障安全，您可能需要提供书面请求，或以其他方式证明您的身份。我们可能会先要求您验证自己的身份，然后再处理您的请求。"),b("br"),n._v("\n● 我们将在15天内做出答复。如您对我们的答复不满意，还可以通过娃娃路客服发起投诉。"),b("br"),n._v("\n● 对于您合理的请求，我们原则上不收取费用，但对多次重复、超出合理限度的请求，我们将视情况收取一定成本费用。对于无端重复、需要过多技术手段（例如，需要开发新系统或从根本上改变现行惯例）、给他人合法权益带来风险或者非常不切实际的请求，我们可能会予以拒绝。"),b("br"),n._v("\n相关限制"),b("br"),n._v("\n● 在以下情形中，按照法律法规要求，我们将无法响应您的请求："),b("br"),n._v("\n○ 1、与国家安全、国防安全有关的；"),b("br"),n._v("\n○ 2、与公共安全、公共卫生、重大公共利益有关的；"),b("br"),n._v("\n○ 3、与犯罪侦查、起诉、审判和执行判决等有关的；"),b("br"),n._v("\n○ 4、有充分证据表明个人信息主体存在主观恶意或滥用权利的；"),b("br"),n._v("\n○ 5、响应您的请求将导致您或其他个人、组织的合法权益受到严重损害的；"),b("br"),n._v("\n○ 6、涉及商业秘密的。"),b("br"),b("br"),n._v("\n关于我们接入的第三方SDK及其可能会收集的个人信息及用途说明："),b("br"),n._v("\n为向用户提供基本服务，我们集成了以下几个第三方SDK"),b("br"),n._v("\n1.微信支付SDK"),b("br"),n._v("\n第三方SDK名称：腾讯SDK"),b("br"),n._v("\n第三方名称：腾讯公司"),b("br"),n._v("\n收集个人信息类型：设备标识符、位置信息、Wi-Fi地址、运营商信息、应用列表、本机号码"),b("br"),n._v("\n使用目的：帮助用户完成腾讯付款"),b("br"),n._v("\n隐私政策链接：腾讯SDK隐私安全说明"),b("br"),b("br"),n._v("\n2.支付宝SDK"),b("br"),n._v("\n• 第三方 SDK 名称：App支付宝客户端SDK"),b("br"),n._v("\n• 第三方名称：支付宝（中国）网络技术有限公司"),b("br"),n._v("\n• 收集的个人信息类型：IMEI、IMSI、MAC 地址、设备序列号、硬件序列号、SIM卡序列号、ICCID、；Android ID、OAID、SSID、BSSID；系统设置、系统属性、设备型号、设备品牌、操作系统；IP 地址、网络类型、运营商信息、Wi-Fi 状态、Wi-Fi 参数、Wi-Fi 列表；软件安装列表。"),b("br"),n._v("\n• 使用目的："),b("br"),n._v("\na. 保障用户账户和资金安全以及支付服务的安全稳定运行。"),b("br"),n._v("\nb. 履行反洗钱、反恐怖融资、反电信网络诈骗等法定义务。"),b("br"),n._v("\nc. 实现网络链路的选择和优化，以提升用户体验。"),b("br"),n._v("\nSDK 隐私说明链接：App支付宝客户端SDK隐私说明 https://opendocs.alipay.com/common/02kiq3"),b("br"),b("br"),n._v("\n3.友盟SDK"),b("br"),n._v("\n第三方SDK名称：友盟SDK"),b("br"),n._v("\n第三方名称：友盟同欣（北京）科技有限公司、北京锐讯灵通科技有限公司"),b("br"),n._v("\n收集个人信息类型: 设备信息 (IMEI/MAC/Android ID/IDFA/OpenUDID/GUID/IP地址/SIM 卡IMSI 信息等)"),b("br"),n._v("\n使用目的：提供统计分析服务，并通过地理位置校准报表数据准确性，提供基础反作弊能力。"),b("br"),n._v("\n隐私政策链接：友盟SDK隐私安全说明 https://www.umeng.com/page/policy"),b("br"),n._v(" "),b("br"),n._v("\n五、我们如何处理未成年人的个人信息"),b("br"),n._v("\n● 本软件不限制使用者年龄，但禁止未成年人自行注册、使用。如需使用，必须由成年人通过手机完成注册并监督使用。所以用户注册时仅需注册成年人手机号和信息。"),b("br"),n._v("\n\n六、存储信息的地点和期限，您的个人信息如何在全球范围转移"),b("br"),n._v("\n● 个人信息存放的地域"),b("br"),n._v("\n我们严格按照法律法规的规定，将境内收集和产生的用户个人信息存放于中国境内。"),b("br"),n._v("\n● 个人信息出境的情况"),b("br"),n._v("\n我们在中华人民共和国境内运营中收集和产生的个人信息，存储在中国境内。如果在未来出现个人信息出境的情况，我们将严格遵守中华人民共和国法律法规的相关规定，同时对出境信息的信息安全进行评估，并获取您的明确授权，但是您通过互联网进行跨境发布动态等个人主动行为除外。"),b("br"),n._v("\n针对以上情形，我们会确保依据本隐私政策对您的个人信息提供足够的保护。"),b("br"),n._v("\n● 存储信息的期限"),b("br"),n._v("\n一般而言，我们仅在为实现目的所必需的最短时间内保留您的个人信息，超过相应期限内的个人信息将会删除或匿名化进行处理。但在下列情况下，我们有可能因需符合法律要求，更改个人信息的存储时间："),b("br"),n._v("\n○ 1.为遵守适用的法律法规或政策等规范性文件的有关规定；"),b("br"),n._v("\n○ 2.为遵守行政机关或类似授权组织的决定等、司法机关判决、裁定、仲裁机关的裁决或其他法律程序的规定；"),b("br"),n._v("\n○ 3.我们有理由确信需要遵守法律法规等有关规定；"),b("br"),n._v("\n○ 4.为执行相关服务协议或本政策、维护社会公共利益，为保护们的客户、我们或我们的关联公司、其他用户或雇员等第三方的人身财产安全或其他合法权益所合理必需的用途。"),b("br"),n._v("\n● 当娃娃路发生停止运营的情形时，我们将采取推送通知、网站或程序内公告等形式通知您，并在合理的期限内删除或匿名化处理您的个人信息。"),b("br"),n._v(" "),b("br"),n._v("\n七、本隐私政策如何更新"),b("br"),n._v("\n● 我们的隐私政策可能变更。如果发生业务功能变更、使用目的变更、个人信息保护相关负责人联络方式变更等情形，我们将相应修订隐私政策。"),b("br"),n._v("\n● 未经您明确同意，我们不会限制您按照本隐私政策所应享有的权利。对于重大变更，我们会提供显著的通知（包括我们会通过娃娃路系统公告等方式等进行通知）。您也可以定期查看本隐私政策，以获取最新的条款。"),b("br"),n._v("\n● 本政策所指的重大变更包括但不限于："),b("br"),n._v("\n1.我们的服务模式发生重大变化。如处理个人信息的目的、处理的个人信息类型、个人信息的使用方式等；"),b("br"),n._v("\n2.个人信息共享、转让或公开披露的主要对象发生变化；"),b("br"),n._v("\n3.您参与个人信息处理方面的权利及其行使方式发生重大变化；"),b("br"),n._v("\n4.我们负责处理个人信息安全的责任部门、联络方式及投诉渠道发生变化时；"),b("br"),n._v("\n5.个人信息安全影响评估报告表明存在高风险时。"),b("br"),n._v("\n● 如果您在接到通知后，选择继续使用我们的服务，即表示同意受经修订的政策约束。"),b("br"),n._v("\n● 我们还会将本政策的旧版本存档，供您查阅，您可通过前述的联系方式向我们申请查阅。"),b("br"),n._v(" "),b("br"),n._v("\n八、广告/我们向您发送的信息"),b("br"),n._v("\n● 我们可能使用您的相关信息，在相关网站、应用、及其他渠道向您发送商业广告。"),b("br"),n._v("\n● 如果您不想接受我们给您发送的商业广告，您可随时通过相应产品退订功能取消。"),b("br"),n._v(" "),b("br"),n._v("\n九、适用范围"),b("br"),n._v("\n● 娃娃路提供的所有服务均使用本隐私政策。但是，请您注意，本隐私政策不适用由其他公司或个人提供的服务，且该服务适用其他公司或个人的隐私政策。"),b("br"),n._v(" "),b("br"),n._v("\n\n十、Bugly SDK 隐私保护声明"),b("br"),n._v("\n娃娃路严格遵守法律法规，按照业界成熟的安全与隐私标准，保护终端用户的个人信息。"),b("br"),n._v("\n本《隐私声明》主要向终端用户说明我们如何处理个人信息（处理包括“收集、存储、使用、加工、传输、提供、公开等”）。同时，将本声明提供给 App 终端用户以便于了解相关内容并获取用户同意。"),b("br"),n._v("\n我们对关键术语进行了定义，请参见本声明“附录 1：关键词定义”。我们对个人敏感信息采用“加黑并斜体”的书写方式进行特别提醒。如对本声明内容有任何疑问、意见或建议，可随时通过本声明第九条提供的方式与我们联系。"),b("br"),n._v("\n本《隐私声明》所称之 Bugly SDK 产品和/或服务包括：Bugly Crash SDK（安卓及 IOS 版）、Bugly 升级 SDK（安卓版）、Bugly 热更新 SDK（IOS 版）以及娃娃路公司不时提供或更新的其他版本。"),b("br"),b("br"),n._v("\n目 录"),b("br"),n._v("\n一、如何收集和使用终端用户的个人信息"),b("br"),n._v("\n二、App 终端用户的授权同意 "),b("br"),n._v("\n三、如何共享、转让、公开披露终端用户的个人信息"),b("br"),n._v("\n四、如何存储 App终端用户的个人信息"),b("br"),n._v("\n五、如何保护 App终端用户的个人信息安全"),b("br"),n._v("\n六、App 终端用户如何管理其个人信息"),b("br"),n._v("\n七、如何处理儿童个人信息"),b("br"),n._v("\n八、如何变更与更新本声明"),b("br"),n._v("\n九、如何联系我们"),b("br"),n._v("\n十、其它"),b("br"),n._v("\n附录：关键词定义"),b("br"),n._v("\n      \n一、如何收集和使用终端用户的个人信息"),b("br"),n._v("\n我们遵循正当、合法、必要的原则，基于 APP 崩溃分析及更新能力的目的，收集和使用如下个人信息："),b("br"),n._v("\n1、终端用户主动提供或我们直接收集的个人信息；"),b("br"),n._v("\n2、从 App 开发者获取的终端用户的个人信息。"),b("br"),n._v("\n我们会在本声明中载明收集的个人信息用途，如果我们要将收集个人信息用于本声明未载明的其它用途，我们会以合理的方式向终端用户告知。"),b("br"),n._v("\n（一）App 终端用户主动提供或我们直接收集的个人信息"),b("br"),n._v("\n为实现各类 Bugly SDK 的特定业务功能，我们可能需要向终端用户收集相关个人信息，主要包括：日志信息（包括：开发者自定义日志、Logcat 日志以及 APP 崩溃堆栈信息）、设备 ID（包括：androidid 以及 idfv）、联网信息、系统名称、系统版本以及国家码。"),b("br"),n._v("\n（二）以下情形中，我们收集、使用个人信息无需征得终端用户的授权同意："),b("br"),n._v("\n1、与个人信息控制者履行法律法规规定的义务相关的；"),b("br"),n._v("\n2、与国家安全、国防安全直接相关的；"),b("br"),n._v("\n3、与公共安全、公共卫生、重大公共利益直接相关的；"),b("br"),n._v("\n4、与刑事侦查、起诉、审判和判决执行等直接相关的；"),b("br"),n._v("\n5、出于维护个人信息主体或其他个人的生命、财产等重大合法权益但又难以得到本人同意的；"),b("br"),n._v("\n6、所涉及的个人信息是个人信息主体自行向社会公众公开的；"),b("br"),n._v("\n7、根据个人信息主体要求签订和履行合同所必需的；"),b("br"),n._v("\n8、从合法公开披露的信息中收集的终端用户的个人信息的，例如：合法的新闻报道、政府信息公开等渠道；"),b("br"),n._v("\n9、维护所提供产品或服务的安全稳定运行所必需的，例如：发现、处置产品或服务的故障。"),b("br"),n._v("\n（四）个人信息的使用规则"),b("br"),n._v("\n1、我们会根据本声明，并仅为实现 Bugly SDK 产品和/或服务功能，对所收集的个人信息进行处理。若需要将收集的个人信息用于其他目的，我们在获得终端用户同意后进行使用。"),b("br"),n._v("\n2、在收集终端用户的个人信息后，我们将通过技术手段对个人信息进行去标识化或匿名化处理。"),b("br"),n._v("\n3、SDK 产品和/或服务停止运营后，或者终端用户撤回个人信息的授权后，或者在终端用户注销账号后，我们将会于合理的时间内销毁或匿名化处理从终端用户处接收的所有个人信息，除非法律另有规定。 "),b("br"),n._v("\n二、App 终端用户的授权同意"),b("br"),n._v("\n将 Bugly SDK 产品和/或服务集成到其 App 中，为向终端用户提供 Bugly SDK 产品和/或服务，我们会以去标识化或匿名方式收集、存储、加工来自于终端用户的个人信息。"),b("br"),n._v("\n1、遵守并将持续遵守适用的法律、法规和监管要求收集、使用和处理 App 终端用户的个人信息，包括但不限于制定和公布有关个人信息保护声明或隐私政策等；"),b("br"),n._v("\n2、告知 App 终端用户并且已经获得终端用户充分、必要且明确的授权、同意和许可（包括获取了儿童监护人对提供终端用户是儿童的个人信息的授权同意）、为提供 Bugly SDK 产品和/或服务以及与 App 功能对应的目的，我们会收集和共享以及如何使用（包括允许我们根据本声明的规定收集和处理）App 终端用户的个人信息；"),b("br"),n._v("\n3、除非适用法律另有规定，App 开发者已经告知终端用户并且获得终端用户充分必要的授权、同意和许可，允许我们对已经收集的个人信息进行去标识化处理，并且在符合相关法律法规的前提下，可以将收集、处理的信息用于本声明第一条列明的用途；"),b("br"),n._v("\n4. 向终端用户提供了易于操作的用户权利实现机制，并说明了终端用户可以如何以及何时行使选择权、如何访问、更正其个人信息，以及行使删除权、更改其授权同意的范围等操作。"),b("br"),n._v("\n\n三、如何共享、转让、公开披露 App 开发者和/或终端用户的个人信息"),b("br"),n._v("\n（一）共享"),b("br"),n._v("\n我们会与我们的关联公司共享必要的个人信息，且受本声明中所提及目的的约束。"),b("br"),n._v("\n我们可能会向合作伙伴及第三方共享终端用户的必要的个人信息，以保障为终端用户提供的服务顺利完成。我们的合作伙伴无权将共享的个人信息用于任何其他用途。"),b("br"),n._v("\n我们会要求合作伙伴提供数据安全能力和信息安全资质（例如：等级保护测评、信息安全管理体系等）证明。在个人敏感信息的处理上，我们会要求第三方采用数据脱敏加密技术，从而更好地保护个人信息。如果 终端用户对第三方处理个人信息有异议或发现这些第三方存在风险时，请按照本声明第九条所述方式联系我们。"),b("br"),n._v("\n（二）转让"),b("br"),n._v("\n我们不会将终端用户的个人信息转让给任何公司、组织和个人，但以下情况除外："),b("br"),n._v("\n1、     事先获得终端用户明确的同意或授权；"),b("br"),n._v("\n2、     在涉及合并、收购、资产转让或类似的交易时，如涉及到个人信息转让，我们会要求新的持有终端用户个人信息的公司、组织继续受本隐私声明的约束，否则，我们将要求该公司、组织重新向终端用户征求授权同意。"),b("br"),n._v("\n（三）公开披露"),b("br"),n._v("\n我们不会公开披露终端用户的个人信息，除非："),b("br"),n._v("\n1、获得终端用户的明确同意后；"),b("br"),n._v("\n2、在法律、法律程序、诉讼或政府主管部门强制要求的情况下。"),b("br"),n._v("\n（四）共享、转让、公开披露个人信息时事先征得授权同意的例外"),b("br"),n._v("\n请理解，在以下情形中，根据法律法规及国家标准，我们共享、转让、公开披露终端用户的个人信息，无需事先征得终端用户的授权同意："),b("br"),n._v("\n1、 与个人信息控制者履行法律法规规定的义务相关的；"),b("br"),n._v("\n2、 与国家安全、国防安全有关的；"),b("br"),n._v("\n3、 与公共安全、公共卫生、重大公共利益直接相关的；"),b("br"),n._v("\n4、 与刑事侦查、起诉、审判和判决执行等直接相关的；"),b("br"),n._v("\n5、 出于维护 终端用户或其他个人的生命、财产等重大合法权益但又很难得到本人同意的；"),b("br"),n._v("\n6、 终端用户自行向社会公众公开的个人信息；"),b("br"),n._v("\n7、 从合法公开披露的信息中收集个人信息的，如合法的新闻报道、政府信息公开等渠道。"),b("br"),n._v("\n四、如何存储终端用户的个人信息"),b("br"),n._v("\n（一）存储方式和期限"),b("br"),n._v("\n我们会通过安全的方式存储终端用户的信息，包括本地存储、数据库和服务器日志。"),b("br"),n._v("\n一般情况下，我们只会在为实现本声明所述目的所必需的最短时间内或法律法规规定或个人信息主体另行授权同意的条件/范围内存储终端用户的个人信息。但在下列情况下，且仅出于下列情况相关的目的，我们有可能需要较长时间保留终端用户的个人信息："),b("br"),n._v("\n1、遵守适用的法律法规等有关规定；"),b("br"),n._v("\n2、 遵守法院判决、裁定或其他法律程序的要求；"),b("br"),n._v("\n3、 遵守相关政府机关或其他有权机关的要求；"),b("br"),n._v("\n4、 为执行相关服务协议或本声明、维护社会公共利益、处理投诉/纠纷，保护我们的客户、我们或我们的关联公司、其他用户或雇员的人身和财产安全或合法权益所合理必需的用途。"),b("br"),n._v("\n（二）存储地域"),b("br"),n._v("\n我们会按照法律法规规定，将境内收集的个人信息存储于中国境内。"),b("br"),n._v("\n五、如何保护终端用户的个人信息安全"),b("br"),n._v("\n（一）安全保护措施"),b("br"),n._v("\n我们已使用符合业界标准的安全防护措施保护终端用户提供的个人信息，防止数据遭到未经授权访问、公开披露、使用、修改、损坏或丢失。 "),b("br"),n._v("\n我们采用业界领先的技术保护措施。我们使用的技术手段包括但不限于防火墙、加密（例如 SSL）、去标识化或匿名化处理、访问控制措施等。此外，我们还会不断加强将 SDK 集成到 App 上的安全能力。"),b("br"),n._v("\n我们建立了保障个人信息安全专门的管理制度、流程和组织。我们也会审查该管理制度、流程和组织，以防未经授权的人员擅自访问、使用或披露用户的信息。"),b("br"),n._v("\n（二）安全事件处置措施"),b("br"),n._v("\n若发生个人信息泄露、损毁、丢失等安全事件，我们会启动应急预案，阻止安全事件扩大。安全事件发生后，我们会及时以推送通知、邮件等形式向终端用户告知安全事件的基本情况、我们即将或已经采取的处置措施和补救措施。"),b("br"),n._v("\n六、App 终端用户如何管理其个人信息"),b("br"),n._v("\n我们非常重视 App 终端用户对个人信息的管理，并尽全力提供对个人信息的查询、访问、修改、删除、投诉举报以及设置隐私功能等的相关权利，以使 App终端用户有能力保障自身的隐私和信息安全。"),b("br"),n._v("\n1、当终端用户所使用的 App 中某项功能由 Bugly SDK 产品和/或服务提供，终端用户可以在使用我们服务的过程中，访问、修改和删除向 App 开发者提供的注册信息和其他个人信息，也可按照本声明第九条所述方式与我们联系；"),b("br"),n._v("\n2、当终端用户直接向我们主张个人信息主体权利时，应提供必要的证明文件，我们还会对终端用户进行身份验证。我们会在保障终端用户 App 账号安全的情况下，响应终端用户的相关请求； "),b("br"),n._v("\n3、当终端用户直接向SDK提供方主张个人信息主体权利时，根据 App 开发者的隐私政策或个人信息保护声明，SDK提供方还可能将与终端用户个人信息相关的请求直接发送给App 开发者，要求其处理和/或寻求帮助。"),b("br"),n._v("\n（三）响应 App 终端用户的合理请求"),b("br"),n._v("\n我们会相应 App 终端用户上述的合理请求，如无端重复、需要过多技术手段（例如，需要开发新系统或从根本上改变现行惯例）、给他人合法权益带来风险或者非常不切实际（例如，涉及备份磁带上存放的信息）的请求，我们可能会予以拒绝。"),b("br"),n._v("\n在以下情形中，我们将无法响应 App终端用户的请求："),b("br"),n._v("\n1、 与我们履行法律法规规定的义务相关的；"),b("br"),n._v("\n2、 与国家安全、国防安全直接相关的；"),b("br"),n._v("\n3、 与公共安公共卫生、重大公共利益直接相关的；"),b("br"),n._v("\n4、 与犯罪侦查、起诉、审判和执行判决等直接相关的；"),b("br"),n._v("\n5、 我们有充分证据表明 App 终端用户存在主观恶意或滥用权利的；"),b("br"),n._v("\n6、 出于维护 App 终端用户或其他个人的生命、财产等重大合法权益但又很难得到本人同意的；"),b("br"),n._v("\n7、 响应 App 终端用户的请求将导致 App 开发者或其他个人、组织的合法权益受到严重损害的；"),b("br"),n._v("\n8、 涉及商业秘密的。"),b("br"),n._v("\n如 App 终端用户的对上述权利实现存在疑问，可以根据本声明第九条所述方式与我们联系。"),b("br"),n._v("\n七、如何处理儿童个人信息"),b("br"),n._v("\nApp 注册用户均为成人，无需提供儿童个人信息。若注册后有儿童使用， 该 App 终端用户（儿童）的监护人必须确保已经阅读并同意了 App 的隐私政策/个人信息保护声明。"),b("br"),n._v("\n如果我们在不知情的情况下收集了儿童的个人信息，我们将及时对其进行删除，除非法律要求我们保留此类资料。如果终端用户认为我们错误或意外地向儿童收集了信息，请按本声明第九条所述方式及时联系我们。如果未获得儿童的监护人同意向我们提供儿童个人信息的，我们将尽快删除该儿童的个人信息并确保不对其进一步处理。"),b("br"),n._v("\n八、如何变更与更新本声明"),b("br"),n._v("\n为提供更好的服务以及随着本平台产品和/或服务的不断发展与变化，我们可能会适时对本声明进行修订。"),b("br"),n._v("\n当本声明的条款发生变更时，我们会在版本更新时以网站公告等方式进行提示，并说明生效日期。"),b("br"),n._v("\n对于重大变更，我们还会提供更为显著的通知（包括对于某些服务，我们会"),b("br"),n._v("\n通过电子邮件或站内信形式或公告形式发送通知，说明本声明的具体变更内容）。因此，请随时查看和了解本声明。"),b("br"),n._v("\n本声明所指的重大变更包括但不限于："),b("br"),n._v("\n1、 我们的服务模式发生重大变化。如处理个人信息的目的、类型、个人信息的使用方式等；"),b("br"),n._v("\n2、 我们在所有权结构、组织架构等方面发生重大变化。如业务调整、破产并购等引起的所有者变更等；"),b("br"),n._v("\n3、 个人信息共享、转让或公开披露的主要对象发生变化；"),b("br"),n._v("\n4、 个人信息处理方面的权利及其行使方式发生重大变化；"),b("br"),n._v("\n5、 负责处理个人信息安全的责任部门、联络方式及投诉渠道发生变化时；"),b("br"),n._v("\n6、个人信息安全影响评估报告表明存在高风险时。"),b("br"),n._v("\n九、如何联系我们"),b("br"),n._v("\n如 App 开发者和/或终端用户对本声明或个人信息相关事宜有疑问，可以通过以下方式与我们取得联系：（i）通过微信公众号“娃娃路”与我们联系进行在线咨询；（ii）发送邮件至：yey@wawalooo.com。我们将及时验证请求人身份并尽快审核所涉问题，并十五个工作日内予以回复。"),b("br"),n._v("\n十、其它"),b("br"),n._v("\n《娃娃路隐私政策》是娃娃路统一适用的一般性隐私条款，其中所规定的用户权利及信息安全保障措施均适用于终端用户。如《娃娃路隐私政策》与本声明存在不一致或矛盾之处，请以本声明为准。"),b("br"),n._v("\n如果 App 终端用户对我们收集和使用个人信息的法律依据有疑问或需要进一步信息的，请根据本声明第九条所述方式与我们联系。"),b("br"),n._v(" "),b("br"),n._v("\n附录：关键词定义"),b("br"),n._v("\n本声明中使用的特定词语，具有如下含义："),b("br"),n._v("\n1、我们或娃娃路：指北京智同世纪科技有限公司。"),b("br"),n._v("\n2、Bugly SDK 产品或服务：指北京智同世纪科技有限公司及其关联公司使用的 SDK 产品和/或服务。"),b("br"),n._v("\n3、App 开发者：指北京智同世纪科技有限公司。"),b("br"),n._v("\n4、App 终端用户：指使用嵌入 Bugly SDK 产品和/或服务的 App 终端用户。"),b("br"),n._v("\n5、应用程序产品和/或服务：指通过接入 Bugly SDK 产品和/或服务，App 开发者自行开发并向 App 终端用户提供产品和/或服务。"),b("br"),n._v("\n6、关联公司：是指与北京智同世纪科技有限公司合并报表范围内的下属公司或其他关联企业。上述公司中任何一方现在或将来控制、受控制或与其处于共同控制下。 "),b("br"),n._v("\n7、控制：是指直接或间接地拥有影响所提及公司管理的能力，无论是通过所有权、有投票权的股份、合同或其他被依法认定的方式。"),b("br"),n._v("\n8、个人信息：指以电子或者其他方式记录的能够单独或者与其他信息结合识别特定自然人身份或者反映特定自然人活动情况的各种信息。"),b("br"),n._v("\n9、用户：通过使用产品和/或服务将其所持有的个人信息交托于数据控制者控制的自然人。"),b("br"),n._v("\n10、 儿童：指未满 14 周岁的未成年人。"),b("br"),n._v("\n11、个人敏感信息：指一旦泄露、非法提供或滥用可能危害人身和财产安全，极易导致个人名誉、身心健康受到损害或歧视性待遇等的个人信息。"),b("br"),n._v("\n12、去标识化：指通过对个人信息的技术处理，使其在不借助额外信息的情况下，无法识别个人信息主体的过程。"),b("br"),n._v("\n13、匿名化：指通过对个人信息的技术处理，使得个人信息主体无法被识别，且处理后的信息不能被复原的过程。"),b("br"),n._v("\n14、 中国或中国境内：指中华人民共和国大陆地区，仅为本声明之目的，不包含香港特别行政区、澳门特别行政区和台湾地区。 "),b("br"),b("br"),n._v("\n北京智同世纪科技有限公司\n        ")])])}]};var p=b("VU/8")({name:"index"},_,!1,function(n){b("5/Uj")},null,null).exports;new v.a({components:{index:p},render:function(n){return n(p)}}).$mount("#app")}},["XWcV"]);
